import org.junit.jupiter.api.Test;

class ExternalValuePreparationTest {

	@Test
	void explicitInitializerVisitsConstantsBoundVarsAndBindingAssignmentsWithoutDynamicContext() {
		Value constant = SimpleValueFactory.getInstance().createIRI("urn:test:constant");
		Value bound = SimpleValueFactory.getInstance().createIRI("urn:test:bound");
		Value assigned = SimpleValueFactory.getInstance().createIRI("urn:test:assigned");
		MapBindingSet row = new MapBindingSet();
		row.addBinding("assigned", assigned);
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(List.of(row));
		StatementPattern pattern = new StatementPattern(Var.of("s", bound), new Var("p"), new Var("o"));
		Extension expression = new Extension(new Join(pattern, assignment));
		expression.addElement(new ExtensionElem(new ValueConstant(constant), "constant"));
		Set<Value> initialized = Collections.newSetFromMap(new IdentityHashMap<>());
		ExternalValuePreparation.initializeQueryModel(expression, initialized::add);
		assertTrue(initialized.contains(constant));
		assertTrue(initialized.contains(bound));
		assertTrue(initialized.contains(assigned));
		assertEquals(3, initialized.size());
	}

	@Test
	void outboundRowsKeepCapturedInitializerAfterDynamicScopeCloses() {
		Value value = SimpleValueFactory.getInstance().createIRI("urn:test:row");
		MapBindingSet row = new MapBindingSet();
		row.addBinding("v", value);
		Set<Value> initialized = Collections.newSetFromMap(new IdentityHashMap<>());
		CloseableIteration<BindingSet> output;
		try (QueryExecutionContext.Activation ignored = QueryExecutionContext
				.activateExternalValueInitializer(initialized::add)) {
			output = ExternalValuePreparation.initializeBindings(new SingletonIteration<>(row));
		}
		assertTrue(initialized.isEmpty());
		try (output) {
			assertSame(row, output.next());
		}
		assertTrue(initialized.contains(value));
	}
}
